/bin/bash -lc "python - <<'PY'
from openpyxl import load_workbook
from pathlib import Path
for p in sorted(Path('inputs').glob('*.xlsx')):
    print('FILE', p.name)
    wb=load_workbook(p, read_only=True, data_only=False)
    for ws in wb.worksheets:
        print('SHEET', repr(ws.title), 'ROWS', ws.max_row, 'COLS', ws.max_column)
        for i,row in enumerate(ws.iter_rows(min_row=1,max_row=min(12,ws.max_row),values_only=True),1):
            vals=[]
            for v in row[:min(20,ws.max_column)]:
                if v is None: vals.append('')
                elif isinstance(v,str): vals.append(v[:120].replace('\\n',' '))
                else: vals.append(f'<{type(v).__name__}>')
            print(i, vals)
    print()
PY"

/bin/bash -lc "python - <<'PY'
from openpyxl import load_workbook
from pathlib import Path
for p in sorted(Path('inputs').glob('*.xlsx')):
    print('FILE', p.name)
    wb=load_workbook(p, read_only=True, data_only=False)
    for ws in wb.worksheets:
        print('SHEET', repr(ws.title), 'ROWS', ws.max_row, 'COLS', ws.max_column)
        for i,row in enumerate(ws.iter_rows(min_row=1,max_row=min(12,ws.max_row),values_only=True),1):
            vals=[]
            for v in row[:min(20,ws.max_column)]:
                if v is None: vals.append('')
                elif isinstance(v,str): vals.append(v[:120].replace('\\n',' '))
                else: vals.append(f'<{type(v).__name__}>')
            print(i, vals)
    print()
PY"

